package pca

// The JSON Schema (draft 2020-12) documents of the PCA wire types (PCActn, Capability, the discovery document) and a small
// dependency-free STRUCTURAL validator. The schemas describe structure only (fields, JSON types, required); they cannot express
// security invariants (signature, attenuation, plan membership, iat < exp). Passing means "well-formed", never "authorized". Every
// object is open (additionalProperties true) so an unknown future field never fails structural validation.
//
// The validator implements only the keywords these schemas use: type (incl. unions), enum, required, properties,
// additionalProperties:false, items, and local '#/...' $ref. No pattern/format/oneOf/anyOf/bounds (minItems is published in the
// schema for external validators but is not enforced here): for full validation feed the schemas to a draft-2020-12 validator.

const schemaAllJSON = `{"PCActn":{"$schema":"https://json-schema.org/draft/2020-12/schema","$id":"https://atlasauth.net/schemas/pca/pcactn.schema.json","title":"PCActn","description":"Proof-Carrying Authority action object (spec §7, wire format v2).","type":"object","required":["ver","action","grant_ref","cap_chain","plan","attestation","provenance","freshness","counter","risk_claim","aud","iat","exp","sig"],"properties":{"ver":{"type":"integer"},"action":{"$ref":"#/$defs/action"},"grant_ref":{"type":"string"},"cap_chain":{"type":"array","minItems":1,"items":{"$ref":"#/$defs/capability"}},"plan":{"$ref":"#/$defs/plan"},"attestation":{"$ref":"#/$defs/attestation"},"provenance":{"$ref":"#/$defs/provenance"},"freshness":{"$ref":"#/$defs/freshness"},"counter":{"type":"integer"},"risk_claim":{"$ref":"#/$defs/riskClaim"},"aud":{"type":"string"},"iat":{"type":"integer"},"exp":{"type":"integer"},"nonce":{"type":"string"},"caution":{"type":"number"},"rationale_commitment":{"type":"string"},"progress_step":{"type":"object","additionalProperties":true},"prohibition_evidence":{"type":["object","array"]},"tool_binding":{"type":"string"},"alg":{"type":"string","enum":["ed25519","ml-dsa-65","hybrid-ed25519-ml-dsa-65"]},"pq_pk":{"type":"string"},"sig":{"type":"string"},"pq_sig":{"type":"string"},"threshold":{"type":"object","additionalProperties":true},"zk_compliance":{"description":"Opaque zk-compliance proof; shape is verifier-defined."},"bond_ref":{"type":"string"}},"additionalProperties":true,"$defs":{"caveat":{"type":"object","required":["type"],"properties":{"type":{"type":"string"}},"additionalProperties":true},"capability":{"type":"object","required":["id","issuer","holder","caveats","body_digest","sig"],"properties":{"id":{"type":"string"},"issuer":{"type":"string"},"holder":{"type":"string"},"caveats":{"type":"array","items":{"$ref":"#/$defs/caveat"}},"parent":{"type":"string"},"body_digest":{"type":"string"},"sig":{"type":"string"},"alg":{"type":"string","enum":["ed25519","ml-dsa-65","hybrid-ed25519-ml-dsa-65"]},"pq_pk":{"type":"string"},"pq_sig":{"type":"string"}},"additionalProperties":true},"action":{"type":"object","required":["verb","resource","params_digest","reversibility_class"],"properties":{"verb":{"type":"string"},"resource":{"type":"string"},"params_digest":{"type":"string"},"reversibility_class":{"type":"string"}},"additionalProperties":true},"inclusionProof":{"type":"object","required":["index","size","path"],"properties":{"index":{"type":"integer"},"size":{"type":"integer"},"path":{"type":"array","items":{"type":"object","additionalProperties":true}}},"additionalProperties":true},"plan":{"type":"object","required":["root","inclusion_proof","node_id"],"properties":{"root":{"type":"string"},"inclusion_proof":{"$ref":"#/$defs/inclusionProof"},"node_id":{"type":"string"},"conditions_digest":{"type":"string"}},"additionalProperties":true},"riskClaim":{"type":"object","required":["r","inputs"],"properties":{"r":{"type":"number"},"inputs":{"type":"object","additionalProperties":true}},"additionalProperties":true},"attestation":{"type":"object","required":["quote_digest","epoch","model_id","measurement","operator"],"properties":{"quote_digest":{"type":"string"},"epoch":{"type":"integer"},"model_id":{"type":"string"},"measurement":{"type":"string"},"operator":{"type":"string"}},"additionalProperties":true},"provenance":{"type":"object","required":["causal_hash","taint_level","trusted_refs"],"properties":{"causal_hash":{"type":"string"},"taint_level":{"type":"number"},"trusted_refs":{"type":"array","items":{"type":"string"}}},"additionalProperties":true},"freshness":{"type":"object","required":["beacon_ref","epoch","accumulator_witness"],"properties":{"beacon_ref":{"type":"string"},"epoch":{"type":"integer"},"accumulator_witness":{"type":"string"}},"additionalProperties":true}}},"Capability":{"$schema":"https://json-schema.org/draft/2020-12/schema","$id":"https://atlasauth.net/schemas/pca/capability.schema.json","title":"Capability","description":"An attenuable capability chain hop (spec §5.2).","type":"object","required":["id","issuer","holder","caveats","body_digest","sig"],"properties":{"id":{"type":"string"},"issuer":{"type":"string"},"holder":{"type":"string"},"caveats":{"type":"array","items":{"$ref":"#/$defs/caveat"}},"parent":{"type":"string"},"body_digest":{"type":"string"},"sig":{"type":"string"},"alg":{"type":"string","enum":["ed25519","ml-dsa-65","hybrid-ed25519-ml-dsa-65"]},"pq_pk":{"type":"string"},"pq_sig":{"type":"string"}},"additionalProperties":true,"$defs":{"caveat":{"type":"object","required":["type"],"properties":{"type":{"type":"string"}},"additionalProperties":true}}},"PcaDiscoveryDocument":{"$schema":"https://json-schema.org/draft/2020-12/schema","$id":"https://atlasauth.net/schemas/pca/discovery.schema.json","title":"PcaDiscoveryDocument","description":"The .well-known/pca-configuration discovery document (internet-wide integration).","type":"object","required":["audience","pca_versions","signature_suites","action_header"],"properties":{"audience":{"type":"string"},"pca_versions":{"type":"array","items":{"type":"integer"}},"signature_suites":{"type":"array","items":{"type":"string"}},"action_header":{"type":"string"},"required_checks":{"type":"array","items":{"type":"string"}},"endpoints":{"$ref":"#/$defs/endpoints"},"trusted_roots":{"type":"array","items":{"type":"string"}},"metadata":{"type":"object","additionalProperties":true}},"additionalProperties":true,"$defs":{"endpoints":{"type":"object","properties":{"attestation_challenge":{"type":"string"},"revocation_epoch":{"type":"string"},"liveness_beacon":{"type":"string"},"stepup":{"type":"string"},"grant":{"type":"string"}},"additionalProperties":true}}}}`

// SchemaDraft is the JSON Schema dialect of the published documents.
const SchemaDraft = "https://json-schema.org/draft/2020-12/schema"

// AllSchemas returns a fresh copy of the published schemas by name: PCActn, Capability, PcaDiscoveryDocument.
func AllSchemas() map[string]any {
	v, err := ParseJSONLenient([]byte(schemaAllJSON))
	if err != nil {
		panic("pca: the published schemas do not parse")
	}
	return v.(map[string]any)
}

// PcactnSchema is the PCActn wire schema.
func PcactnSchema() map[string]any { return AllSchemas()["PCActn"].(map[string]any) }

// CapabilitySchema is the Capability wire schema.
func CapabilitySchema() map[string]any { return AllSchemas()["Capability"].(map[string]any) }

// DiscoverySchema is the discovery document schema.
func DiscoverySchema() map[string]any { return AllSchemas()["PcaDiscoveryDocument"].(map[string]any) }
